-- Read-back for scripts/migrations/20261006240000_m820_guideline_criteria.sql (DWA-M 820 guideline criteria). READ ONLY.
-- Run BEFORE the apply (step 0: R0 to R3 — R4 errors until the apply has created its ledgers, prod-query prints ERROR and goes on) and AFTER (R0 to R4). Expected values come from the embedded-Postgres harness
-- tests/harness/m820-guideline-criteria.integration.test.ts. No comment line ends with a semicolon (prod-query.mjs splits on semicolon + newline).
-- md5 per gate = md5(severity | condition | description | clause_reference).

-- R0 · per standard: gates in the pre-state / in the block's post-state / neither. Before: at_pre = n (REQ-31 waits for 20261006230000). After: at_post = n
SELECT v.std, count(*) AS n,
       sum((md5(cr.severity || '|' || cr.condition || '|' || coalesce(cr.description, '') || '|' || coalesce(cr.clause_reference, '')) = v.pre)::int) AS at_pre,
       sum((md5(cr.severity || '|' || cr.condition || '|' || coalesce(cr.description, '') || '|' || coalesce(cr.clause_reference, '')) = v.post)::int) AS at_post,
       sum((md5(cr.severity || '|' || cr.condition || '|' || coalesce(cr.description, '') || '|' || coalesce(cr.clause_reference, '')) NOT IN (v.pre, v.post))::int) AS neither,
       string_agg(CASE WHEN md5(cr.severity || '|' || cr.condition || '|' || coalesce(cr.description, '') || '|' || coalesce(cr.clause_reference, '')) NOT IN (v.pre, v.post) THEN v.code END, ',' ORDER BY v.code) AS neither_codes
