  ('DWA-M-820-3','M8203-16','REQ-22','0a98acc5d04c973748b6392bf8157949','8dbdd7b13941b1190dcc88865d91951b','warn'),
  ('DWA-M-820-3','M8203-17','REQ-13','6189f2f26c21c2b07862d1cbf1d62222','6189f2f26c21c2b07862d1cbf1d62222','block'),
  ('DWA-M-820-3','M8203-17','REQ-13-2','4fe665c6bee37ffdb988db4d9224cb9b','4fe665c6bee37ffdb988db4d9224cb9b','block'),
  ('DWA-M-820-3','M8203-17','REQ-13-3','f7f5f915200b6db07a8eff75e375f6f0','9640df2b029a4f67c664229dbfc3c244','warn'),
  ('DWA-M-820-3','M8203-17','REQ-23','47695c09b9ec4a1ba0535bac1cb5c57f','e4dfe58a7bf8c06581fe197e4f5bbb2c','warn'),
  ('DWA-M-820-3','M8203-18','REQ-14','1b467dfdfb09838a65a923eb97477455','1b467dfdfb09838a65a923eb97477455','block'),
  ('DWA-M-820-3','M8203-18','REQ-14-2','c707bb579c9b3f92dea262865cb6f1a3','c707bb579c9b3f92dea262865cb6f1a3','block'),
  ('DWA-M-820-3','M8203-18','REQ-14-3','51c5711cd58861ab19cc74d2cbf8ae3c','a75828a929fe45e9023da82eaa33a9a4','warn'),
  ('DWA-M-820-3','M8203-18','REQ-24','a4823ee5991fda0e319138a53262c183','5910d3731b1a24dfbe6edd1d6cf2d08a','warn'),
  ('DWA-M-820-3','M8203-19','REQ-25','dfb6155f324ebce09950ee8965af015b','dfb6155f324ebce09950ee8965af015b','warn'),
  ('DWA-M-820-3','M8203-19','REQ-26','9312f8fcfa684507f27fe2bf47f50460','9312f8fcfa684507f27fe2bf47f50460','warn'),
  ('DWA-M-820-3','M8203-20','REQ-27','d8059903ea4e559165a33acc93105874','d8059903ea4e559165a33acc93105874','warn'),
  ('DWA-M-820-3','M8203-20','REQ-28','2fbc342c7cd70c79fd51810ea8029be4','2fbc342c7cd70c79fd51810ea8029be4','warn'),
  ('DWA-M-820-3','M8203-21','REQ-29','acf151c62b17957efb7cdd4da27bd321','acf151c62b17957efb7cdd4da27bd321','warn'),
  ('DWA-M-820-3','M8203-21','REQ-30','172ac267b5760097e20e3f0736d5be8f','172ac267b5760097e20e3f0736d5be8f','warn'),
  ('DWA-M-820-3','M8203-23','REQ-20','1801bc923674a0cefbce9cab0092e61f','c13f7fb15f3e094fd4af49afd0194889','warn'),
  ('DWA-M-820-3','M8203-23','REQ-21','dc88ca84486a1ace54ce30f29bb5799d','678354b5f61d2760e0d6af56679753a5','warn'),
  ('DWA-M-820-3','M8203-24','REQ-31','1b60e65d723ccb7758f55a1eef0e65b7','497b4ae02117e4849973e940fd15cef3','block'),
  ('DWA-M-820-3','M8203-24','REQ-32','6b3ce2d2127dbbbb924eb906fc30ebe6','ecad01f8ce9c5a8b9b17b3634729ae28','warn')) AS v(std, ws, code, pre, post, sev_after)
  JOIN standards s ON s.code = v.std JOIN worksheet_templates w ON w.standard_id = s.id AND w.code = v.ws
  JOIN compliance_requirements cr ON cr.worksheet_template_id = w.id AND cr.code = v.code
 GROUP BY v.std ORDER BY v.std;

-- R1 · severity per standard (before: 820-1 20 block / 6 warn, 820-2 45 / 16, 820-3 20 / 30) and whether block 20261006230000 is applied
SELECT s.code AS std, sum((cr.severity = 'block')::int) AS block, sum((cr.severity = 'warn')::int) AS warn, sum((cr.severity NOT IN ('block','warn'))::int) AS other,
       (SELECT count(*) FROM equations e JOIN worksheet_templates we ON we.id = e.worksheet_template_id WHERE we.code = 'M8203-24' AND e.equation_number = 'M8203-24-D1' AND md5(e.formula) = '0e7c0e64ba6c08ac022ea68a58e71ed3') AS projektstopp_paths_applied
  FROM compliance_requirements cr JOIN worksheet_templates w ON w.id = cr.worksheet_template_id JOIN standards s ON s.id = w.standard_id
 WHERE s.code LIKE 'DWA-M-820%' GROUP BY s.code ORDER BY s.code;

-- R2 · fields / tables / equations (before → after): tokens 0 → 3, E rows 0 → 10, ANHB23 rows 8 → 9, new fields 0 → 4, E-filtered equations 0 → 72,
-- register E column 0 → 12, *_items_rated new labels 0 → 12, required phase goals 65 → 67, applicable_* at § 6.1 0 → 2, change_log label 0 → 1
SELECT
  (SELECT count(*) FROM fields f, jsonb_array_elements(f.enum_values) e WHERE f.active AND e->>'value' IN ('vergleichbare_institution','keine','monatlich')
     AND f.symbol IN ('client_organization_type','projektsteuerung_scope','mgmt_cycle_frequency')) AS tokens,
  (SELECT count(*) FROM regulation_table_rows r JOIN regulation_tables t ON t.id = r.table_id WHERE t.standard_code = 'DWA-M-820-3' AND r.row_key = 'E') AS qe_e_rows,
  (SELECT count(*) FROM regulation_table_rows r JOIN regulation_tables t ON t.id = r.table_id WHERE t.standard_code = 'DWA-M-820-1' AND t.table_code = 'ANHB23') AS anhb23_rows,
  (SELECT count(*) FROM fields f JOIN worksheet_templates w ON w.id = f.worksheet_template_id WHERE w.code IN ('M8203-19','M8203-21')
     AND f.symbol IN ('bim_roles_defined','bim_planning_data_digital','bim_model_communication','bim_tools_training')) AS new_goal_fields,
  (SELECT count(*) FROM equations e JOIN worksheet_templates w ON w.id = e.worksheet_template_id JOIN standards s ON s.id = w.standard_id
     WHERE s.code = 'DWA-M-820-3' AND e.formula LIKE '%nr != ''E''%') AS e_filtered_equations,
  (SELECT count(*) FROM fields f, jsonb_array_elements(f.ui_config->'columns') c
     WHERE f.symbol LIKE 'qe%items' AND c->>'key' = 'kriterium_ergaenzung') AS registers_with_e_column,
  (SELECT count(*) FROM fields f WHERE f.symbol LIKE 'qe%items_rated' AND f.label_de LIKE '%ohne Ergänzungen%') AS rated_labels_new,
  (SELECT count(*) FROM fields f JOIN worksheet_templates w ON w.id = f.worksheet_template_id JOIN standards s ON s.id = w.standard_id
     WHERE s.code = 'DWA-M-820-3' AND f.symbol ~ '^pz_[0-9]+_[0-9]+_status$' AND f.is_required) AS required_phase_goals,
  (SELECT count(*) FROM fields f WHERE f.symbol IN ('applicable_din_standards','applicable_dwa_standards') AND f.clause_reference = '§6.1') AS applicable_at_6_1,
  (SELECT count(*) FROM fields f WHERE f.symbol = 'change_log_present' AND f.label_de = 'Änderungsregister vorhanden') AS change_log_label_new;

-- R3 · the gates whose behaviour changes: severity, guard and clause now (after: the post column of 47_)
SELECT s.code AS std, w.code AS ws, cr.code, cr.severity, cr.clause_reference, left(cr.condition, 60) AS condition_head
  FROM compliance_requirements cr JOIN worksheet_templates w ON w.id = cr.worksheet_template_id JOIN standards s ON s.id = w.standard_id
 WHERE (s.code, w.code, cr.code) IN (('DWA-M-820-1','M820-01','REQ-01'),('DWA-M-820-1','M820-04','REQ-02'),('DWA-M-820-1','M820-10','REQ-11'),('DWA-M-820-1','M820-14','REQ-14'),('DWA-M-820-1','M820-14','REQ-15'),('DWA-M-820-1','M820-18','REQ-19'),('DWA-M-820-1','M820-20','REQ-20'),('DWA-M-820-1','M820-21','REQ-21'),('DWA-M-820-1','M820-24','REQ-23'),('DWA-M-820-1','M820-25','REQ-25'),('DWA-M-820-2','820-2-01','REQ-01'),('DWA-M-820-2','820-2-02','REQ-26'),('DWA-M-820-2','820-2-04','REQ-53'),('DWA-M-820-2','820-2-08','REQ-15'),('DWA-M-820-2','820-2-16','REQ-35'),('DWA-M-820-2','820-2-20','REQ-42'),('DWA-M-820-2','820-2-21','REQ-45'),('DWA-M-820-2','820-2-22','REQ-50'),('DWA-M-820-2','820-2-25','REQ-54'),('DWA-M-820-2','820-2-26','REQ-56'),('DWA-M-820-2','820-2-27','REQ-57'),('DWA-M-820-2','820-2-27','REQ-59'),('DWA-M-820-3','M8203-01','REQ-01'),('DWA-M-820-3','M8203-02','REQ-05'),('DWA-M-820-3','M8203-24','REQ-31'),('DWA-M-820-3','M8203-24','REQ-32'))
 ORDER BY 1, 2, 3;

-- R4 · archives / ledgers (after: gates 46, fields 34, equations 72, written 152, added 15; a re-apply keeps them)
SELECT (SELECT count(*) FROM compliance_requirements_archive_m820_gc) AS gate_archive, (SELECT count(*) FROM fields_archive_m820_gc) AS field_archive, (SELECT count(*) FROM equations_archive_m820_gc) AS equation_archive,
       (SELECT count(*) FROM m820_gc_written) AS written, (SELECT count(*) FROM m820_gc_added) AS added;
